import {injectDrift,endTrial,clone,NODES,PAIRS,newDesign,capacity,cost,designTests,capture,filterCapture,TEMPLATES,newIac,iacRun,iacValid,CONCEPTS} from './workshop-model.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const MISSIONS=[
 {id:'concept',tag:'01 / PROTOCOL',title:'届いたのは、どの層まで？',brief:'復興隊から届く短い報告を読み、次に確かめるべきことを判断する。まず予測し、結果の意味を確かめよう。',goal:'DNS・ICMP・TCP・HTTPについて、証拠から言える範囲を3つの場面で判断する。',hints:['成功したプロトコルと、その上で動くサービスを分けよう。','「通信できる」を、名前が引ける・接続できる・応答が返るに分解しよう。'],limits:'選択問題は概念の確認。実践的な調査能力は基礎課題と次のキャプチャ課題で別途確かめます。',lore:'protocol は外交上の儀礼・取り決めを表す語から。通信する双方の約束事です。'},
 {id:'capture',tag:'02 / PACKET FORENSICS',title:'届かなかった返事',brief:'端末側で保存した incident.pcap 相当の教材記録を調べる。DNSは解決したようだが、書庫が開かない。フィルターで必要な通信を取り出そう。',goal:'TCPの記録を観測し、再送と拒否応答を区別する。別の障害記録でも診断して2件を完了する。',hints:['まずTCP 443の往復を見る。SYNに何が返っている？','同じSeqのSYNだけなら無応答。RST, ACKなら拒否応答。無応答の場所までは断定できない。'],limits:'実pcapの読み込みや実パケット採取ではなく、教材用の固定レコードです。tcpdumpの限定構文を再現。TLS暗号文からHTTPの内容は表示しません。',lore:'capture は「捕らえる」。観測点の外で起きたことは、その点の記録だけでは決められません。'},
 {id:'ha',tag:'03 / HIGH AVAILABILITY',title:'一つ失っても、灯りを守る',brief:'二つの電源系統を使えるようになった。配線、書庫の台数、設置先を決めて、単一機器の故障と片系統の停電に耐える都市網を作ろう。',goal:'端末以外の各機器を1台ずつ停止しても到達可能。西または東の電源系統が落ちても到達可能。',hints:['経路が2本あっても、同じ機器や電源を通るなら同時に失う。','端末から別スイッチ・別関所・別書庫へ2経路を作り、それぞれ別の電源へ。書庫Bを有効にしよう。'],limits:'転送可能なグラフとして評価。端末自体は冗長化対象外。L2ループ、STP、VRRPの収束、ステート同期、戻り経路はモデル化していません。',lore:'冗長性は余分な構成を備える性質。信頼性工学では「共通原因故障」が、単純な台数増加の落とし穴になります。'},
 {id:'security',tag:'04 / SECURITY',title:'通す道、閉じる道',brief:'住民にはHTTPSを公開し、SSHとDBは公開しない。遠隔の支店からはVPNで私設網へ接続する。前の設計を引き継ぎ、接続の可否を両側から試そう。',goal:'HTTPS許可・SSH拒否・DB拒否・VPNと私設経路の成立をすべて検証する。',hints:['接続できることと、接続できないことを受入条件にする。','トンネルだけでは宛先への経路はできない。VPNと私設網への経路を両方設定しよう。'],limits:'ゾーン間ポリシーの簡略モデル。実FWの規則順序、conntrack、VPN鍵交換・暗号処理は扱いません。',lore:'firewall はもともと延焼を防ぐ防火壁。ネットワークでは通信を選別する境界です。'},
 {id:'performance',tag:'05 / CAPACITY PLANNING',title:'祭りの日の通信網',brief:'通常100 Mbpsだった需要が、祭りの日には300 Mbpsになる。配線の帯域と書庫の処理能力を増やし、片方の書庫が止まっても150 Mbpsを処理したい。',goal:'通常100・ピーク300・書庫A停止時150 Mbpsを満たし、予算28単位以内に収める。',hints:['端末から書庫までの全経路を見る。サーバーだけ増やしても細いリンクは残る。','2本の独立経路を各200 Mbps、書庫2台を各200 Mbpsにすると、経路6本＋書庫で20単位。'],limits:'リンク容量とサーバー容量から最大フローを計算。値はモデル上の上限で、実測やTCPスループットではありません。遅延・損失・輻輳制御は省略。',lore:'スループットは単位時間に処理できる量。帯域を増やすときは費用と障害時の余力も同時に評価します。'},
 {id:'netplan',tag:'06 / IaC · NETPLAN',title:'設定を、再現できる形に',brief:'端末設定をYAMLで宣言する。設計台帳は192.168.10.20/24、出口192.168.10.1、DNS192.168.10.53。構文を検証して試験適用し、接続を確かめて確定しよう。',goal:'generateによる構文確認、tryによる試験適用、接続検証、確定後の再検証を行う。',hints:['構文が正しくても接続できるとは限らない。addressesとviaを台帳と比較する。','アドレスを192.168.10.20/24、viaを192.168.10.1に変更。generate→try→接続検証→確定→接続検証。'],limits:'テンプレートのaddresses・via・DNSのみ解釈します。tryの自動タイムアウトは手動取消で模擬。実Linuxへは適用しません。',lore:'宣言的設定は「どう変更するか」より「どの状態であってほしいか」を記述します。'},
 {id:'ansible',tag:'07 / IaC · ANSIBLE',title:'二つの書庫に、同じ約束を',brief:'inventory.iniのwebグループにはweb-aとweb-b。HTTPS設定済みのnginxを起動し、自動起動を有効にするPlaybookを用意する。差分確認後に2回実行しよう。',goal:'check/diff後に2台へ適用。2回目はchanged=0、両方のサービスが起動・自動起動する。',hints:['stateとenabledは別の設定。今動くことと再起動後に動くことを区別する。','state: started、enabled: true。check/diff→適用→もう一度適用→検証。'],limits:'ansible.builtin.serviceを1タスクだけ解釈する模型。インベントリは固定。SSHや実Ansibleは実行しません。',lore:'冪等性は同じ操作を繰り返しても結果が変わらない性質。数学の f(f(x)) = f(x) に対応します。'},
 {id:'terraform',tag:'08 / IaC · TERRAFORM',title:'設計と現実のずれを戻す',brief:'既存の模擬VPCへ2つのサブネットを作る。同じAZへの偏りを直し、保存した計画から適用する。その後の手動変更（drift）を計画で検出して復旧しよう。',goal:'異なるAZの2サブネットを作り、手動変更後の再計画・再適用・検証まで完了する。',hints:['2リソースあってもAZが同じなら場所の分散にならない。','eastのAZをap-northeast-1cへ。plan→apply→手動変更→plan→apply→検証。'],limits:'aws_subnetのHCL断片を模型内で解釈します。実行にはAWS provider設定・認証・実在VPCが別途必要。stateのロックや秘密管理は未再現です。',lore:'drift は漂流・ずれ。宣言した設定と、手で変更された実際の状態との差を指します。'}
];
let saved;try{saved=JSON.parse(localStorage.getItem('packetbound-workshop-v1'))}catch{}
let data=saved?.version===1?saved:{version:1,current:0,done:[],notes:{},hints:{},design:newDesign(),iac:{},records:{},concept:0,captureSolved:[]};
// Persisted data belongs to this application; recover safely from a damaged save.
if(!Array.isArray(data.design?.links)||!Array.isArray(data.done)||!data.notes||!data.iac){data={version:1,current:0,done:[],notes:{},hints:{},design:newDesign(),iac:{},records:{},concept:0,captureSolved:[]};}
data.current=Math.max(0,Math.min(7,Number(data.current)||0));
let captureRows=[],captureVariant='drop',currentCaptureObserved=false,measured=false,failedNode='',revealedConcept=false;
const mission=()=>MISSIONS[data.current];
function save(){try{localStorage.setItem('packetbound-workshop-v1',JSON.stringify(data));$('#saveStatus').textContent='ブラウザに自動保存'}catch{$('#saveStatus').textContent='保存できません。ストレージを確認してください。'}}
function feedback(text){$('#feedback').textContent=text;}
function complete(){const id=mission().id;if(!data.done.includes(id))data.done.push(id);save();navigation();$('#completion').innerHTML='<div class="successCard"><b>✦ 要件を検証しました</b><p>調査ノートに「判断の根拠」と「別の条件では成立しない点」を残そう。'+(data.hints[id]?'ヒントを利用した達成です。別の条件で再挑戦して確かめよう。':'')+'</p><button id="advance">'+(data.current===7?'達成記録を見る':'次の課題へ →')+'</button></div>';$('#advance').onclick=()=>{if(data.current===7){$('#completion').innerHTML='<div class="successCard"><h3>復興工房の記録</h3>'+MISSIONS.map(m=>'<p>'+ (data.done.includes(m.id)?'✓ ':'◇ ')+esc(m.title)+'</p>').join('')+'<p>達成は保存されています。左の課題から再検証できます。自力で説明できない箇所は調査ノートとログに戻りましょう。</p></div>';return}data.current++;render()};}
function navigation(){$('#progress').textContent=`発展工房 ${data.done.length} / 8 達成`;$('#missions').innerHTML=MISSIONS.map((m,i)=>`<button data-mission="${i}" class="${data.current===i?'current':''}">${data.done.includes(m.id)?'✓':'◇'} ${m.title}<small>${m.tag}</small></button>`).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{data.current=+b.dataset.mission;render()});}
function render(){const m=mission();navigation();$('#chapter').textContent=m.tag;$('#title').textContent=m.title;$('#brief').textContent=m.brief;$('#goal').textContent='達成目標：'+m.goal;$('#limits').textContent=m.limits;$('#aside').textContent=m.lore;$('#notes').value=data.notes[m.id]||'';$('#help').open=false;$('#completion').innerHTML='';feedback('');revealedConcept=false;measured=false;$('#hint').textContent=m.hints[0];$('#nextHint').hidden=false;
 if(m.id==='concept')renderConcept();else if(m.id==='capture'){captureVariant=data.captureSolved.includes('drop')?'refuse':'drop';renderCapture();}else if(['ha','security','performance'].includes(m.id))renderDesign();else renderIac();save();}
$('#notes').oninput=e=>{data.notes[mission().id]=e.target.value;save()};$('#help').ontoggle=()=>{if($('#help').open){data.hints[mission().id]=Math.max(1,data.hints[mission().id]||0);save()}};$('#nextHint').onclick=()=>{data.hints[mission().id]=2;$('#hint').textContent=mission().hints[1];$('#nextHint').hidden=true;save()};
function renderConcept(){const i=Math.min(data.concept,2),q=CONCEPTS[i];$('#stage').innerHTML=`<div class="panel"><span class="eyebrow">予測 ${i+1} / 3</span><h3>${esc(q.question)}</h3>${q.choices.map((v,n)=>`<button class="choice" data-choice="${n}">${esc(v)}</button>`).join('')}<div id="conceptResult" role="status"></div><button id="conceptNext" hidden>別の場面へ →</button></div>`;
 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const correct=+b.dataset.choice===q.answer;$('#conceptResult').textContent=(correct?'判断は適切です。':'この観測からは、その結論を支持できません。')+q.explain;if(correct){revealedConcept=true;$('#conceptNext').hidden=false}else data.records.conceptRetries=(data.records.conceptRetries||0)+1;save()});$('#conceptNext').onclick=()=>{if(!revealedConcept)return;if(data.concept>=2){complete();$('#conceptNext').hidden=true}else{data.concept++;renderConcept();save()}};}
function renderCapture(){captureRows=[];currentCaptureObserved=false;$('#stage').innerHTML=`<div class="panel"><div class="actions"><span class="pill">端末 eth0 / 教材記録</span><label>調査する記録 <select id="captureSelect"><option value="drop">記録 A</option><option value="refuse">記録 B</option><option value="ok">正常記録（比較用）</option></select></label></div><form class="cmdform" id="captureForm"><input type="text" id="captureCommand" aria-label="tcpdumpコマンド" placeholder="tcpdump -nn -r incident.pcap"><button class="primary">記録を読む</button></form><details><summary>構文リファレンス</summary><p><code>tcpdump -nn -r incident.pcap 'tcp and port 443'</code></p><p>-nnはアドレスとポートの名前変換を無効にし、-rは保存ファイルを読みます。フィルターはtcp、port 443、port 53、host 10.20.0.80、tcp and port 443に対応。</p></details><div class="tablewrap" id="packets">まだ記録を読んでいません。</div><div id="packetDetail" class="support"></div></div><div class="panel"><h3>証拠から判断する</h3><button class="choice" data-diagnosis="drop">SYNは再送されているが応答なし。破棄地点や原因はまだ特定できない。</button><button class="choice" data-diagnosis="refuse">RST応答が返った。接続を拒否しているが、待受停止だけとは断定できない。</button><button class="choice" data-diagnosis="ok">TCPは成立。暗号化されたTLSデータからHTTPの内容は読めない。</button><p class="support" id="captureProgress"></p></div>`;
 $('#captureSelect').value=captureVariant;$('#captureSelect').onchange=e=>{captureVariant=e.target.value;renderCapture();feedback('新しい記録を選びました。前の観測はこの記録の証拠には使いません。')};$('#captureProgress').textContent=`調査済み ${data.captureSolved.length}/2 件`;
 $('#captureForm').onsubmit=e=>{e.preventDefault();try{captureRows=filterCapture($('#captureCommand').value,capture(captureVariant));currentCaptureObserved=captureRows.some(r=>r.no===4&&r.port===443);$('#packets').innerHTML='<table><thead><tr><th>No.</th><th>秒</th><th>送信元 → 宛先</th><th>Protocol</th><th>Info</th></tr></thead><tbody>'+captureRows.map(r=>`<tr><td><button data-packet="${r.no}">${r.no}</button></td><td>${r.time.toFixed(3)}</td><td>${r.src} → ${r.dst}</td><td>${r.protocol}</td><td>${esc(r.info)}</td></tr>`).join('')+'</tbody></table>';document.querySelectorAll('[data-packet]').forEach(b=>b.onclick=()=>{const r=captureRows.find(r=>r.no===+b.dataset.packet);$('#packetDetail').textContent=`#${r.no}: ${r.protocol==='DNS'?'DNSの問い合わせ/応答。名前解決の証拠。':r.protocol==='TLS'?'暗号化ペイロード。HTTP本文はこの観測から読めません。':'TCPヘッダのフラグとSeq/Ack、時間差を比較してください。'} 観測点は端末eth0。`});feedback(captureRows.length+' 件を表示。証拠を選んで判断してください。');}catch(err){feedback(err.message)}};
 document.querySelectorAll('[data-diagnosis]').forEach(b=>b.onclick=()=>{if(!currentCaptureObserved){feedback('先にTCPの応答または再送を含む記録を観測してください。DNSだけではこの診断の根拠になりません。');return}if(b.dataset.diagnosis!==captureVariant){feedback('表示したフラグと時間差を見直そう。原因の断定と、観測できた事実を区別してください。');return}if(captureVariant!=='ok'&&!data.captureSolved.includes(captureVariant))data.captureSolved.push(captureVariant);save();$('#captureProgress').textContent=`調査済み ${data.captureSolved.length}/2 件`;feedback('記録に整合する診断です。別の記録でも調査してみよう。');if(data.captureSolved.length===2)complete();});}
function graph(){const d=data.design;return `<svg class="graph" viewBox="0 0 750 400" role="img" aria-label="2系統のスイッチ、関所、書庫を接続する設計図">${d.links.map(l=>{const a=NODES.find(n=>n.id===l.a),b=NODES.find(n=>n.id===l.b);return `<path d="M${a.x} ${a.y}L${b.x} ${b.y}" class="${l.on?'wire':'off'}"/>${measured&&capacity(d,failedNode?[failedNode]:[])>0&&l.on&&l.a!==failedNode&&l.b!==failedNode?`<path d="M${a.x} ${a.y}L${b.x} ${b.y}" class="flow"/>`:''}`}).join('')}${NODES.map(n=>`<g transform="translate(${n.x},${n.y})" opacity="${failedNode===n.id||n.id==='srvB'&&d.servers===1?.3:1}"><rect x="-43" y="-29" width="86" height="58" rx="${n.type==='server'?3:10}" fill="#20372b" stroke="#9fb98c"/><path d="M-28-12h56M-28 0h40M-28 12h20" stroke="#749774" stroke-width="3"/><circle cx="28" cy="13" r="4" fill="${failedNode===n.id?'#dd967f':'#accf88'}"/><text y="51" text-anchor="middle">${n.name}</text><text y="68" text-anchor="middle">${n.id==='client'?'操作端末':d.domains[n.id]==='west'?'西電源':'東電源'}${n.id==='srvB'&&d.servers===1?' / 未設置':''}</text></g>`).join('')}</svg>`;}
function invalidateDesign(){measured=false;data.records[mission().id]=null;$('#completion').innerHTML='';$('#measurement').textContent='設定変更により測定値は失効しました。';$('#testResults').innerHTML='設定を変更しました。受入試験を再実行してください。';$('#diagram').innerHTML=graph();save();}
function renderDesign(){const d=data.design,id=mission().id;
 $('#stage').innerHTML=`<div id="diagram">${graph()}</div><p class="support">点線は未接続。リンクを追加すると配線が現れます。配線図は常時表示し、測定値は試験後に表示します。点の移動は配線の強調表示で、実際のフロー配分ではありません。</p><div class="split"><div class="panel"><h3>配線と容量</h3>${d.links.map((l,i)=>`<div class="linkrow"><label><input type="checkbox" data-link="${i}" ${l.on?'checked':''}>${esc(l.a)} ↔ ${esc(l.b)}</label><select data-cap="${i}" aria-label="${l.a} ${l.b}の帯域">${[100,200,500].map(c=>`<option ${l.capacity===c?'selected':''} value="${c}">${c} Mbps</option>`).join('')}</select></div>`).join('')}<label>書庫の台数 <select id="servers"><option value="1" ${d.servers===1?'selected':''}>1台</option><option value="2" ${d.servers===2?'selected':''}>2台</option></select></label><label>各書庫の処理能力 <select id="serverCapacity">${[100,200,500].map(c=>`<option value="${c}" ${d.serverCapacity===c?'selected':''}>${c} Mbps</option>`).join('')}</select></label></div><div><div class="panel"><h3>${id==='security'?'ゾーン間ポリシー':'故障ドメイン'}</h3>${id==='security'?['https','ssh','db','vpn','privateRoute'].map((k,i)=>`<label><input type="checkbox" data-policy="${k}" ${d[k]?'checked':''}>${['外部 → HTTPSを許可','外部 → SSHを許可','外部 → DBを許可','支店VPNを確立','VPN経由の私設網経路を設定'][i]}</label>`).join(''):Object.entries(d.domains).map(([k,v])=>`<label>${k} <select data-domain="${k}"><option value="west" ${v==='west'?'selected':''}>西電源</option><option value="east" ${v==='east'?'selected':''}>東電源</option></select></label>`).join('')}<p class="support">予算：有効リンク帯域÷100 ＋ 各書庫(処理能力÷100＋2)。電源分離の費用はモデル外。</p></div><div class="panel"><h3>任意の障害を観測</h3><label>停止する機器 <select id="fault"><option value="">停止なし</option>${NODES.filter(n=>n.id!=='client').map(n=>`<option value="${n.id}">${n.name}</option>`).join('')}</select></label><button id="probe">到達性・容量を測る</button><div id="measurement" class="support">未観測</div></div></div></div><button class="primary" id="testDesign">すべての受入試験を実行する</button><div class="panel" id="testResults">${data.records[id]?esc(data.records[id]):'未検証。達成目標の全条件を試験します。'}</div>`;
 document.querySelectorAll('[data-link]').forEach(e=>e.onchange=()=>{d.links[+e.dataset.link].on=e.checked;invalidateDesign()});document.querySelectorAll('[data-cap]').forEach(e=>e.onchange=()=>{d.links[+e.dataset.cap].capacity=+e.value;invalidateDesign()});document.querySelectorAll('[data-domain]').forEach(e=>e.onchange=()=>{d.domains[e.dataset.domain]=e.value;invalidateDesign()});document.querySelectorAll('[data-policy]').forEach(e=>e.onchange=()=>{d[e.dataset.policy]=e.checked;invalidateDesign()});$('#servers').onchange=e=>{d.servers=+e.target.value;invalidateDesign()};$('#serverCapacity').onchange=e=>{d.serverCapacity=+e.target.value;invalidateDesign()};$('#fault').value=failedNode;$('#fault').onchange=e=>{failedNode=e.target.value;measured=false;$('#measurement').textContent='条件が変わりました。再測定してください。';$('#diagram').innerHTML=graph()};$('#probe').onclick=()=>{measured=true;const c=capacity(d,failedNode?[failedNode]:[]);$('#measurement').textContent=`到達性: ${c>0?'あり':'なし'} / 集約容量上限: ${c} Mbps / 予算: ${cost(d)} 単位（モデル値）`;$('#diagram').innerHTML=graph()};$('#testDesign').onclick=()=>{const results=designTests(d,id);$('#testResults').innerHTML=results.map(t=>`<div class="test ${t.pass?'':'fail'}"><b>${t.pass?'✓':'×'}</b> ${esc(t.label)}</div>`).join('');data.records[id]=results.map(t=>(t.pass?'✓ ':'× ')+t.label).join('\n');save();if(results.every(t=>t.pass)){feedback('すべての条件を、この構成で確認しました。');complete()}else feedback('未達条件があります。観測・設計変更・再試験を繰り返してください。');};}
const COMMANDS={netplan:['sudo netplan generate','sudo netplan try','netplan status'],ansible:['ansible-playbook -i inventory.ini site.yml --check --diff','ansible-playbook -i inventory.ini site.yml'],terraform:['terraform plan -out=tfplan','terraform apply tfplan','terraform state list']};
const PURPOSE={netplan:'generateは構文からバックエンド設定を生成し、tryは確認付きの試験適用、statusは現在状態の確認です。',ansible:'--checkは変更を予測し、--diffは差分を表示。-iは対象ホストのインベントリ。通常実行で適用し、再実行で冪等性を観測します。',terraform:'plan -outは差分計画を保存。apply tfplanは保存済みの計画を適用。state listは管理対象を一覧表示します。'};
function renderIac(){const kind=mission().id;data.iac[kind]??=newIac(kind);const s=data.iac[kind];
 $('#stage').innerHTML=`<div class="split"><div class="panel"><h3>${kind==='netplan'?'/etc/netplan/01-network.yaml':kind==='ansible'?'site.yml':'main.tf'}</h3><p class="support">対応範囲内の構文を編集します。実環境への適用はありません。</p><textarea id="config" rows="18" spellcheck="false" aria-label="構成ファイル"></textarea>${kind==='ansible'?'<details><summary>inventory.ini（読み取り専用）</summary><pre>[web]\nweb-a\nweb-b</pre></details>':''}<details><summary>対応する構文と資料</summary><p>${PURPOSE[kind]}</p><p>${mission().limits}</p><a href="${kind==='netplan'?'https://netplan.readthedocs.io/en/stable/netplan-tutorial/':kind==='ansible'?'https://docs.ansible.com/projects/ansible/latest/playbook_guide/playbooks_checkmode.html':'https://developer.hashicorp.com/terraform/cli/commands/plan'}" target="_blank" rel="noreferrer">公式資料 ↗</a></details></div><div><div class="panel"><h3>変更の実行と観測</h3><form class="cmdform" id="iacForm"><input type="text" id="iacCommand" aria-label="IaCコマンド" placeholder="コマンドを入力"><button class="primary">実行</button></form><details><summary>構文リファレンス（クリックで入力）</summary><div class="commands">${COMMANDS[kind].map((c,i)=>`<button data-command="${i}">${esc(c)}</button>`).join('')}</div><p class="support">${PURPOSE[kind]}</p></details><pre class="terminal" id="iacLog">${esc(s.log||'まだ実行していません。')}</pre>${kind==='netplan'?'<div class="actions"><button id="confirmTrial">試験設定を確定</button><button id="cancelTrial">取消・ロールバック</button></div>':kind==='terraform'?'<button id="drift">模擬環境を手動変更する（drift）</button>':''}</div><button class="primary" id="verifyIac">${kind==='netplan'?'接続と設定を検証':'受入条件を検証'}</button><div id="iacState" class="support"></div></div></div>`;
 $('#config').value=s.text;$('#config').oninput=e=>{s.text=e.target.value;s.verified=false;$('#completion').innerHTML='';save()};document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{$('#iacCommand').value=COMMANDS[kind][+b.dataset.command];$('#iacCommand').focus()});
 const output=text=>{s.log=((s.log||'')+'\n'+text).slice(-8000);$('#iacLog').textContent=s.log;$('#iacLog').scrollTop=$('#iacLog').scrollHeight;save()};
 $('#iacForm').onsubmit=e=>{e.preventDefault();const c=$('#iacCommand').value;try{output('$ '+c+'\n'+iacRun(s,c));$('#completion').innerHTML='';feedback('結果を端末に表示しました。必要に応じて再検証してください。')}catch(err){output('ERROR: '+err.message)}save()};
 if(kind==='netplan'){$('#confirmTrial').onclick=()=>{if(s.trial===null){feedback('試験適用中ではありません。');return}if(!s.verified){feedback('確定前に「接続と設定を検証」で観測してください。');return}endTrial(s,true);output('試験設定を確定しました。最後に再検証してください。')};$('#cancelTrial').onclick=()=>{if(s.trial===null){feedback('取り消す試験適用がありません。');return}endTrial(s,false);output('試験前の設定へロールバックしました。')}}
 if(kind==='terraform')$('#drift').onclick=()=>{const key=Object.keys(s.actual)[0];if(!key){feedback('まずplanとapplyで構築してください。');return}injectDrift(s);$('#completion').innerHTML='';output('模擬環境でサブネットを1個削除。保存済み計画があれば古くなりました。')};
 $('#verifyIac').onclick=()=>{if(kind==='netplan'&&s.trial!==null){const ok=s.actual.address==='192.168.10.20/24'&&s.actual.gateway==='192.168.10.1'&&s.actual.dns==='192.168.10.53';s.verified=ok;output(ok?'試験中の接続成功。設定を確定して再検証してください。':'接続失敗。設計台帳と比較し、必要なら取消してください。');return}const ok=iacValid(s);s.verified=ok;output('受入試験: '+(ok?'PASS':'FAIL — 達成目標の条件を再確認してください。'));if(ok)complete();else feedback('現在状態だけでなく、差分確認・再適用・変更後の検証も達成目標です。');};
}
render();
